export interface WorkflowDefStep {
  /** canonical step id from workflow_steps */
  stepId: string;
  parentStepId: string;
  /** call / publish / sleep / wait_* / parallel / sequence / local / workflow */
  kind: string;
  /** 0 for top-level, +1 per parent hop (UI indent) */
  depth: number;
  runsTotal: number;
  runsCompleted: number;
  runsFailed: number;
  runsCompensated: number;
  avgDurationMs: number;
  /**
   * Waterfall layout in [0..1], positioned by execution level (how the runner
   * actually schedules steps), not declaration index. Every step that runs at
   * the same level shares an identical offset+width, so concurrency shows as
   * aligned overlapping bars. The top-level list is a waitFor DAG (independent
   * steps share level 0 → parallel; a waitFor dep pushes a step one level
   * later); a "parallel" group overlaps its branches; a "sequence" group stacks
   * its children. offset = level / total_levels, width = span / total_levels.
   * Owner-facing example: a → b → c (chained by waitFor) → offset 0/0.33/0.66,
   * width 0.33 each; a, b with no waitFor → both offset 0, width 0.5 (parallel).
   * Zero-valued when the layout could not be computed (orphan steps not in the
   * declared graph).
   */
  offsetPct: number;
  widthPct: number;
  /**
   * true for steps that do actual work (call / publish / sleep / wait_* /
   * workflow / local). false for composite wrappers (parallel / sequence) —
   * the UI hides those so the schema reads like a real trace waterfall.
   */
  isLeaf: boolean;
}

